mapper.select:
select ca.*,
    su.real_name as studentName,
    sr.real_name as counselorName
from cs_appointment as ca
left join sys_user as su on ca.student_id = su.user_id
left join sys_user as sr on ca.counselor_id = sr.user_id


        and su.real_name like concat('%',#{studentName},'%')    


        and ca.status = #{status}


        and ca.appointment_date = #{appointmentDate}


        and ca.counselor_id = #{counselorId}


        and ca.student_id = #{studentId}


order by create_time desc

mapper.update:
update cs_appointment


        status = #{status},


        confirm_time = #{confirmTime}


where appointment_id = #{id}
